+    @ForceInline
+    int testOOMEHandlerWithNullMerge(boolean cond, int x, int y) {
+        Point p = null;
+        try {
+            if (cond) {
+                p = new Point(y, x);
+            }
+        } catch (OutOfMemoryError ignore) {
+            // Fallthrough to get p == null on OOME
+        }
+        return p == null ? 0 : p.x * p.y;
+    }
